using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/leads"),Authorize] public class LeadsApiController(ApplicationDbContext db,IAuditService audit):ControllerBase {
 private IQueryable<Lead> Scope(){var q=db.Leads.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.AssignedTo==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return q;}
 [HttpGet]public async Task<IActionResult>Get(){return Ok(await Scope().Select(x=>new{x.LeadId,x.LeadCode,x.LeadName,x.Email,x.Phone,x.CompanyName,x.Source,x.Status,x.ExpectedValue}).ToListAsync());}
 [HttpGet("{id:int}")]public async Task<IActionResult>GetById(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.LeadId==id);if(x==null)return NotFound();return Ok(new{x.LeadId,x.LeadCode,x.LeadName,x.Email,x.Phone,x.CompanyName,x.Source,x.Status,x.ExpectedValue,x.AssignedTo,x.IsConverted});}
 [HttpPost]public async Task<IActionResult>Create(Lead input){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(input.Status))return BadRequest(new{message="Invalid lead status."});if(input.ExpectedValue<0)return BadRequest(new{message="Expected value cannot be negative."});input.LeadId=0;input.LeadCode=$"LED-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";input.AssignedTo=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;db.Add(input);await db.SaveChangesAsync();await audit.WriteAsync("Create","Lead",input.LeadId.ToString());return Created($"/api/leads/{input.LeadId}",new{input.LeadId,input.LeadCode,input.LeadName,input.Status});}
 [HttpPut("{id:int}")]public async Task<IActionResult>Update(int id, Lead input){var x=await Scope().FirstOrDefaultAsync(a=>a.LeadId==id);if(x==null)return NotFound();if(!ModelState.IsValid)return ValidationProblem(ModelState);if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(input.Status))return BadRequest(new{message="Invalid lead status."});if(input.ExpectedValue<0)return BadRequest(new{message="Expected value cannot be negative."});x.LeadName=input.LeadName;x.Email=input.Email;x.Phone=input.Phone;x.CompanyName=input.CompanyName;x.Source=input.Source;x.Status=input.Status;x.Priority=input.Priority;x.ExpectedValue=input.ExpectedValue;await db.SaveChangesAsync();await audit.WriteAsync("Update","Lead",id.ToString());return NoContent();}
 [HttpDelete("{id:int}")]public async Task<IActionResult>Delete(int id){var x=await Scope().FirstOrDefaultAsync(a=>a.LeadId==id);if(x==null)return NotFound();x.Status="Lost";x.IsConverted=false;await db.SaveChangesAsync();await audit.WriteAsync("MarkLost","Lead",id.ToString());return NoContent();}
}
